import "dotenv/config";
import express from "express";
import path from "path";
import cors from "cors";
import multer from "multer";
import { Octokit } from "@octokit/rest";
import { createServer as createViteServer } from "vite";
import fs from "fs";
import { initializeApp, App, cert } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";

// Initialize Firebase Admin lazily
let firebaseAdminApp: App | null = null;
function getFirebaseAdmin() {
  if (!firebaseAdminApp) {
    try {
      const serviceAccountJson = process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
      if (serviceAccountJson) {
        try {
          const serviceAccount = JSON.parse(serviceAccountJson);
          firebaseAdminApp = initializeApp({
            credential: cert(serviceAccount)
          });
        } catch (parseError) {
          console.error("Invalid JSON in FIREBASE_SERVICE_ACCOUNT_KEY environment variable.", parseError);
        }
      } else {
        // Fallback to application default credentials (works if hosted on GCP with same project)
        firebaseAdminApp = initializeApp();
      }
    } catch (error) {
      console.warn("Could not initialize Firebase Admin SDK.", error);
    }
  }
  return firebaseAdminApp;
}

// Initialize Octokit lazily to prevent startup crash if GITHUB_PAT is missing
let octokitClient: Octokit | null = null;
function getOctokit() {
  if (!octokitClient) {
    // For development, you can fallback to the PAT provided in the chat if process.env.GITHUB_PAT is empty
    // but in production it MUST be in process.env.GITHUB_PAT
    const token = process.env.GITHUB_PAT;
    octokitClient = new Octokit({ auth: token });
  }
  return octokitClient;
}

const GITHUB_OWNER = process.env.GITHUB_OWNER || "";
const GITHUB_REPO = process.env.GITHUB_REPO || "";

// Helper to dynamically fetch the default branch of the repository
let cachedDefaultBranch: string | null = null;
async function getDefaultBranch(octokit: Octokit): Promise<string> {
  if (cachedDefaultBranch) return cachedDefaultBranch;
  try {
    const { data } = await octokit.repos.get({
      owner: GITHUB_OWNER,
      repo: GITHUB_REPO,
    });
    cachedDefaultBranch = data.default_branch || "main";
    return cachedDefaultBranch;
  } catch (err: any) {
    console.warn("Failed to fetch default branch from GitHub, defaulting to 'main':", err.message);
    return "main";
  }
}

async function startServer() {
  const app = express();
  const PORT = 3000;


  app.use(cors());
  app.use(express.json());
  
  // Debug logging
  app.use((req, res, next) => {
    console.log(`[DEBUG] Incoming request: ${req.method} ${req.url}`);
    next();
  });


  // Setup Multer to store uploaded files in memory
  const upload = multer({ storage: multer.memoryStorage() });

  // Upload endpoint for GitHub

  const baseUrl = process.env.VITE_BASE_URL || '/pustaka-digital/';
  const basePath = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;

  const apiRouter = express.Router();

  // Upload endpoint for GitHub
  apiRouter.post("/upload", upload.single("file"), async (req, res) => {

    try {
      if (!req.file) {
        return res.status(400).json({ error: "No file provided" });
      }

      const octokit = getOctokit();
      const fileBuffer = req.file.buffer;
      const originalName = req.file.originalname;
      const ext = path.extname(originalName);
      
      // Generate a unique filename using timestamp
      const uniqueFilename = `${Date.now()}-${Math.random().toString(36).substring(7)}${ext}`;
      
      // Determine folder path based on file extension and mimetype to be extremely robust
      const extLower = ext.toLowerCase();
      const isPdf = extLower === ".pdf" || req.file.mimetype === "application/pdf";
      const folderPath = isPdf ? "books" : "covers";
      const filePath = `${folderPath}/${uniqueFilename}`;
      
      // Encode file content to Base64 (required by GitHub API)
      const base64Content = fileBuffer.toString("base64");

      const defaultBranch = await getDefaultBranch(octokit);
      let response;

      try {
        // Upload file to GitHub repository on the default branch (e.g. main or master)
        response = await octokit.repos.createOrUpdateFileContents({
          owner: GITHUB_OWNER,
          repo: GITHUB_REPO,
          path: filePath,
          message: `Upload ${isPdf ? 'book PDF' : 'book cover'}: ${originalName}`,
          content: base64Content,
          branch: defaultBranch,
        });
      } catch (branchError: any) {
        console.warn(`Failed to upload file to branch '${defaultBranch}', retrying without branch parameter (empty repository fallback)...`, branchError.message);
        
        // If the repository is completely empty, there are no commits or branches yet.
        // Omit the branch parameter to initialize the default branch and push the first commit.
        response = await octokit.repos.createOrUpdateFileContents({
          owner: GITHUB_OWNER,
          repo: GITHUB_REPO,
          path: filePath,
          message: `Upload ${isPdf ? 'book PDF' : 'book cover'}: ${originalName}`,
          content: base64Content,
        });
      }

      // Construct jsDelivr CDN URL for highly optimized global edge caching (completely free)
      const cdnUrl = `https://cdn.jsdelivr.net/gh/${GITHUB_OWNER}/${GITHUB_REPO}@${defaultBranch}/${filePath}`;

      res.json({ 
        success: true, 
        url: cdnUrl,
        filePath: filePath,
        githubResponse: response.data 
      });
    } catch (error: any) {
      console.error("Upload error:", error);
      res.status(500).json({ error: "Failed to upload file to GitHub", details: error.message });
    }
  });

  // Delete file endpoint for GitHub
  apiRouter.post("/delete-file", async (req, res) => {
    try {
      const { filePath } = req.body;
      if (!filePath) {
        return res.status(400).json({ error: "No filePath provided" });
      }

      // Check if it is a default/placeholder URL/file or doesn't look like a managed path
      const filePathStr = String(filePath);
      if (filePathStr.startsWith("http") || filePathStr.includes("dummy") || !filePathStr.includes("/")) {
        return res.json({ success: true, message: "Skipped deleting default or external path" });
      }

      const octokit = getOctokit();
      const defaultBranch = await getDefaultBranch(octokit);
      try {
        // Get the file content to obtain its SHA
        let sha;
        try {
          const { data } = await octokit.repos.getContent({
            owner: GITHUB_OWNER,
            repo: GITHUB_REPO,
            path: filePathStr,
            ref: defaultBranch,
          });
          sha = (data as any).sha;
        } catch (getErr: any) {
          console.warn(`Failed to get content on branch '${defaultBranch}', retrying without ref parameter...`, getErr.message);
          const { data } = await octokit.repos.getContent({
            owner: GITHUB_OWNER,
            repo: GITHUB_REPO,
            path: filePathStr,
          });
          sha = (data as any).sha;
        }

        if (sha) {
          try {
            await octokit.repos.deleteFile({
              owner: GITHUB_OWNER,
              repo: GITHUB_REPO,
              path: filePathStr,
              message: `Delete book file: ${filePathStr}`,
              sha: sha,
              branch: defaultBranch,
            });
          } catch (delErr: any) {
            console.warn(`Failed to delete file on branch '${defaultBranch}', retrying without branch parameter...`, delErr.message);
            await octokit.repos.deleteFile({
              owner: GITHUB_OWNER,
              repo: GITHUB_REPO,
              path: filePathStr,
              message: `Delete book file: ${filePathStr}`,
              sha: sha,
            });
          }
          console.log(`Successfully deleted file from GitHub: ${filePathStr}`);
        }
      } catch (ghErr: any) {
        // If file not found (404), count as success since it's already gone
        if (ghErr.status === 404) {
          console.warn(`File not found on GitHub, skipping deletion: ${filePathStr}`);
        } else {
          throw ghErr;
        }
      }

      res.json({ success: true, message: "File deleted from GitHub successfully" });
    } catch (error: any) {
      console.error("Delete file error:", error);
      res.status(500).json({ error: "Failed to delete file from GitHub", details: error.message });
    }
  });

  // Health check
  apiRouter.get("/health", (req, res) => {
    res.json({ status: "ok" });
  });

  // Update password endpoint
  apiRouter.post("/users/:uid/password", async (req, res) => {
    try {
      const { uid } = req.params;
      const { password } = req.body;
      
      if (!password || password.length < 6) {
        return res.status(400).json({ error: "Password must be at least 6 characters long." });
      }

      const adminApp = getFirebaseAdmin();
      if (!adminApp) {
        return res.status(500).json({ error: "Firebase Admin SDK is not initialized." });
      }

      await getAuth(adminApp).updateUser(uid, { password });
      res.json({ success: true, message: "Password updated successfully" });
    } catch (error: any) {
      console.error("Update password error:", error);
      let errorMessage = error.message;
      if (errorMessage?.includes("identitytoolkit.googleapis.com")) {
        errorMessage = "Konfigurasi Firebase Admin tidak valid. Tambahkan FIREBASE_SERVICE_ACCOUNT_KEY di Secrets (Environment Variables).";
      }
      res.status(500).json({ error: errorMessage });
    }
  });

  // Delete user endpoint
  apiRouter.post("/users/:uid/delete", async (req, res) => {
    try {
      const { uid } = req.params;
      
      const adminApp = getFirebaseAdmin();
      if (!adminApp) {
        return res.status(500).json({ error: "Firebase Admin SDK is not initialized." });
      }

      await getAuth(adminApp).deleteUser(uid);
      res.json({ success: true, message: "User deleted successfully" });
    } catch (error: any) {
      console.error("Delete user error:", error);
      res.status(500).json({ error: error.message });
    }
  });



  // Mount on all possible paths to guarantee match regardless of env var mismatch between build and runtime
  app.use('/api', apiRouter);
  app.use('/pustaka-digital/api', apiRouter);
  if (basePath && basePath !== '/pustaka-digital') {
    app.use(`${basePath}/api`, apiRouter);
  }

  // Redirect root to base URL if they differ
  app.get('/', (req, res, next) => {

    if (baseUrl !== '/' && req.path === '/') {
      return res.redirect(baseUrl);
    }
    next();
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);


  } else {
    const distPath = path.join(process.cwd(), 'dist');
    // Serve static files mapped to baseUrl
    if (baseUrl !== '/') {
      app.use(baseUrl, express.static(distPath));
    }
    app.use(express.static(distPath));
    
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }




  // Catch 404s and return JSON instead of Express HTML fallback
  app.use((req, res, next) => {
    if (req.path.includes('/api/')) {
      res.status(404).json({ error: `API Route not found: ${req.method} ${req.path}` });
    } else {
      next();
    }
  });

  // Global error handler to ensure API routes always return JSON instead of Express HTML fallback
  app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
    console.error("Express global error handler caught:", err);
    if (res.headersSent) {
      return next(err);
    }
    res.status(err.status || 500).json({ error: err.message || "Internal Server Error" });
  });

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
